/**
 * The official Webcenta logo (public/brand/webcenta-logo-original.png; sizes generated by
 * scripts/generate-icons.mjs) with the wordmark. Used in every portal's header, footer,
 * sign-in pages and error pages.
 */
export function Logo({ wordmark = true }: { wordmark?: boolean }) {
  return (
    <span className="flex items-center gap-2">
      {/* eslint-disable-next-line @next/next/no-img-element -- a fixed 32 px asset; no optimisation needed */}
      <img src="/brand/logo-mark-64.png" srcSet="/brand/logo-mark-64.png 1x, /brand/logo-mark-128.png 2x" width={32} height={32} alt="" className="size-8 rounded-[9px]" />
      {wordmark && <span className="text-lg font-extrabold tracking-tight">Web<span className="text-brand">centa</span></span>}
    </span>
  );
}
